WITH cleaned AS (SELECT *, CAST(quantity AS STRING) AS quantity_num FROM order_items WHERE product_id IS NOT NULL), enriched AS (SELECT *, AVG(quantity) OVER (PARTITION BY order_id ORDER BY quantity, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS quantity_avg_2_prior, NTILE(4) OVER (PARTITION BY order_id ORDER BY unit_price DESC, id) AS unit_price_bucket, ROW_NUMBER() OVER (ORDER BY quantity DESC, id) AS event_seq, LAST_VALUE(quantity) IGNORE NULLS OVER (PARTITION BY product_id ORDER BY unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_quantity FROM cleaned WHERE product_id = 40), joined AS (SELECT e.*, p.discount, p.amount FROM enriched e INNER JOIN orders p ON e.order_id = p.id), matched_keys AS (SELECT id FROM joined INTERSECT SELECT id FROM order_items WHERE order_id IN (6, 16, 26, 27)), verified AS (SELECT s.* FROM joined s INNER JOIN matched_keys k ON s.id = k.id) SELECT order_id, quantity, unit_price, quantity_avg_2_prior, unit_price_bucket, event_seq, last_known_quantity, discount, CUME_DIST() OVER (ORDER BY last_known_quantity DESC) AS last_known_quantity_cume_dist FROM verified
